pub const CHEVRON_RIGHT: &str = r#"<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>"#;

fn svg_icon(svg_bytes: &'static [u8]) -> Svg<'static> {
    Svg::new(svg::Handle::from_memory(svg_bytes))
        .width(Length::Fixed(18.0))
        .height(Length::Fixed(18.0))
}

macro_rules! icon_fn {
    ($name:ident, $svg:expr) => {
        #[allow(dead_code)]
        pub fn $name() -> Svg<'static> {
            svg_icon($svg.as_bytes())
        }
    };
}

icon_fn!(home, HOME);
icon_fn!(folder, FOLDER);
icon_fn!(code, CODE);
icon_fn!(monitor, MONITOR);
icon_fn!(heart, HEART);
icon_fn!(search, SEARCH);
icon_fn!(moon, MOON);
icon_fn!(sun, SUN);
icon_fn!(globe, GLOBE);
